-- Landing page v3: a landing passa a divulgar o que entrou no app depois da v2
-- (troca de exercício, retrospectiva do mês, modo pausa, check-in diário,
-- medidas corporais e desafios com amigos) e ganha os ícones users/pause/repeat
-- (ICONS no <script> da landing <-> ICON_OPTIONS no LandingEditor).
--
-- SÓ sobrescreve a linha se ela ainda for idêntica ao seed da v2
-- (20261002010000): se o admin editou algo pelo painel, nada é alterado, pra
-- não apagar o trabalho dele. Nesse caso, ajuste pelo painel Landing page.
-- Os blocos novos da vitrine (desafios, rotina, retrospectiva) são fixos no
-- HTML e aparecem de qualquer forma.

update public.landing_content
set content = $land$
{"theme":{"primaryColor":"#f97316"},"sections":[{"id":"hero","type":"hero","enabled":true,"badge":"Grátis · sem anúncios · funciona offline","titleTop":"Pare de treinar no improviso.","titleBottom":"Treine com plano e veja","titleHighlight":"cada quilo a mais.","lead":"O EAFIT monta seu treino pelo seu objetivo e nível, guia cada série no modo ao vivo e transforma o que você registra em gráficos, recordes e sequência. Dá pra desafiar os amigos e pausar sem perder a sequência — no celular, mesmo sem internet.","ctaPrimaryLabel":"Começar grátis","ctaSecondaryLabel":"Ver o app por dentro"},{"id":"highlights","type":"highlights","enabled":true,"items":[{"icon":"cloud","label":"Sync entre aparelhos"},{"icon":"download","label":"Instala como app"},{"icon":"wifi-off","label":"Funciona offline"},{"icon":"tag","label":"Grátis e sem anúncios"}]},{"id":"compare","type":"compare","enabled":true,"title":"Treinar por treinar vs. treinar com o EAFIT","subtitle":"A diferença não está no esforço. Está em saber o que fazer e enxergar o resultado.","badLabel":"Sem plano","badItems":["Anota a carga no papel, quando anota","Não lembra quanto levantou na semana passada","Descansa no achismo, olhando o relógio","Não sabe se está evoluindo de verdade","Perde a sequência numa viagem ou semana corrida"],"goodLabel":"Com EAFIT","goodItems":["Treino do dia pronto, com a carga da última vez à vista","Cada série marcada vira histórico automaticamente","Descanso cronometrado, com alarme e +15s","Gráficos, heatmap e recordes mostram o progresso real","Modo pausa e desafios com amigos mantêm você no ritmo"]},{"id":"showcase","type":"showcase","enabled":true,"title":"Feito pra usar no meio do treino","subtitle":"Botões grandes, tela sempre acesa e nada de digitar mais do que o necessário."},{"id":"features","type":"features","enabled":true,"title":"Tudo que você precisa pra treinar sério","subtitle":"Sem planilha, sem app pago, sem depender de internet.","items":[{"icon":"activity","title":"Plano semanal personalizado","description":"Treino dividido por dia da semana, montado pelo seu objetivo e nível, com séries, repetições, descanso e técnica."},{"icon":"zap","title":"Modo treino ao vivo","description":"Tela cheia com um exercício por vez, descanso com alarme e tela sempre acesa enquanto você treina."},{"icon":"repeat","title":"Troca de exercício","description":"Sem o aparelho ou com desconforto? Troque na hora por alternativas do mesmo músculo e do seu nível."},{"icon":"play","title":"Demonstração de execução","description":"Vídeos curtos com câmera lenta e imagens do movimento para 200 exercícios."},{"icon":"calendar","title":"Histórico e retrospectiva","description":"Calendário do mês, tempo, séries e volume, cada sessão comparada com a anterior e uma retrospectiva do mês para compartilhar."},{"icon":"chart","title":"Evolução e recordes","description":"Evolução de carga por exercício, volume por treino, heatmap de 35 dias e seus recordes pessoais."},{"icon":"droplet","title":"Hidratação","description":"Meta diária pelo seu peso, adições rápidas com desfazer, sequência de dias na meta e lembretes."},{"icon":"trophy","title":"Conquistas e sequência","description":"Medalhas por constância, sequência de 7 e 14 dias e marcos de 10, 25, 50, 100 e 200 treinos."},{"icon":"camera","title":"Fotos, peso e medidas","description":"Fotos de progresso, registro de peso e medidas de cintura, braço, coxa e mais, com gráfico da evolução."},{"icon":"users","title":"Desafios com amigos","description":"Crie um desafio, compartilhe o código de convite e vejam quem treina mais dias no período."},{"icon":"pause","title":"Modo pausa e check-in","description":"Pause por 7, 14 ou 30 dias sem perder a sequência e registre energia, sono e humor em 3 toques."},{"icon":"cloud","title":"Offline e sincronizado","description":"Registre sem internet; quando a conexão volta, tudo sincroniza entre celular, tablet e computador."}]},{"id":"steps","type":"steps","enabled":true,"title":"Comece em menos de 2 minutos","subtitle":"Sem download em loja e sem configuração complicada.","items":[{"title":"Crie sua conta","description":"Só e-mail e senha. Abre direto no navegador do celular ou do computador."},{"title":"Conte seu objetivo","description":"Peso, altura, objetivo e nível — o plano da semana sai na hora."},{"title":"Treine, acompanhe e desafie","description":"Marque as séries, veja gráficos e recordes crescerem e convide os amigos para um desafio."}]},{"id":"faq","type":"faq","enabled":true,"title":"Perguntas frequentes","subtitle":"Ainda em dúvida? As respostas mais comuns estão aqui.","items":[{"question":"É grátis mesmo?","answer":"Sim. Não tem plano pago, não tem anúncio e não pede cartão de crédito."},{"question":"Preciso baixar na loja de apps?","answer":"Não. O EAFIT é um app web instalável: abra no navegador e, no Android, toque em “Instalar app” ou “Adicionar à tela inicial”; no iPhone, toque em Compartilhar → “Adicionar à Tela de Início”. Ele passa a abrir em tela cheia, como qualquer app."},{"question":"Funciona sem internet na academia?","answer":"Funciona. Você registra séries e água offline e, quando a conexão volta, tudo é sincronizado sozinho com a sua conta."},{"question":"Posso mudar o treino que o app montou?","answer":"Pode. No editor de treino você troca, adiciona ou remove exercícios e ajusta séries, repetições e descanso. E na hora de treinar, o botão “Trocar exercício” sugere alternativas do mesmo músculo e do seu nível."},{"question":"Como funcionam os desafios com amigos?","answer":"Você cria um desafio (7, 14 ou 30 dias), recebe um código e manda para quem quiser. Quem entra pelo código participa, e vence quem treinar mais dias no período. Os outros só veem seu apelido e sua pontuação."},{"question":"E se eu viajar ou ficar doente?","answer":"Ative o modo pausa no Perfil por 7, 14 ou 30 dias. A sequência de treinos fica protegida e os lembretes de treino são silenciados até você voltar."},{"question":"Serve para quem está começando?","answer":"Serve. No cadastro você escolhe entre iniciante, intermediário e avançado, e os exercícios têm demonstração de execução e dica de técnica."},{"question":"O que acontece com os meus dados?","answer":"Ficam na sua conta, protegidos por login. No Perfil você pode exportar tudo ou excluir a conta quando quiser. Detalhes na Política de Privacidade."}]},{"id":"cta","type":"cta","enabled":true,"title":"Seu próximo treino já pode ficar registrado.","subtitle":"Crie a conta em menos de 2 minutos. Grátis, sem anúncios e funciona offline.","ctaLabel":"Começar agora"}]}
